import CMigration
import Darwin

struct Comparer : Sendable {
  var of_samesort : Bool
  var of_listdir : Bool
  var sorter : Sorter
  var sortfcn : (@Sendable (FTSEntry, FTSEntry) -> ComparisonResult)!

  enum Sorter {
    case name
    case revname
    case mod
    case revmod
    case acc
    case revacc
    case birth
    case revbirth
    case stat
    case revstat
    case size
    case revsize
  }

  init(_ s : Bool, _ d : Bool, _ ss : Sorter) {
    of_samesort = s
    of_listdir = d
    sorter = ss
    sortfcn = switch sorter {
      case .name: namecmp
      case .revname: revnamecmp
      case .mod: modcmp
      case .revmod: revmodcmp
      case .acc: acccmp
      case .revacc: revacccmp
      case .birth: birthcmp
      case .revbirth: revbirthcmp
      case .stat: statcmp
      case .revstat: revstatcmp
      case .size: sizecmp
      case .revsize: revsizecmp
//      default: namecmp
    }
  }

  func namecmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return ComparisonResult(rawValue: strcoll(a.name, b.name))!
  }

  func revnamecmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return ComparisonResult(rawValue: strcoll(b.name, a.name))!
  }

  func modcmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    if b.statp.st_mtim.tv_sec > a.statp.st_mtim.tv_sec {
      return .orderedAscending
    }
    if b.statp.st_mtim.tv_sec < a.statp.st_mtim.tv_sec  {
      return .orderedDescending
    }
    if b.statp.st_mtim.tv_nsec > a.statp.st_mtim.tv_nsec {
      return .orderedAscending
    }
    if b.statp.st_mtim.tv_nsec < a.statp.st_mtim.tv_nsec {
      return .orderedDescending
    }
    if of_samesort {
      return ComparisonResult(rawValue: strcoll(b.name, a.name))!
    }
    else {
      return ComparisonResult(rawValue: strcoll(a.name, b.name))!
    }
  }

  func revmodcmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return (modcmp(b, a));
  }

  func acccmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    if b.statp.st_atim.tv_sec > a.statp.st_atim.tv_sec {
      return .orderedAscending
    }
    if b.statp.st_atim.tv_sec < a.statp.st_atim.tv_sec {
      return .orderedDescending
    }
    if b.statp.st_atim.tv_nsec > a.statp.st_atim.tv_nsec {
      return .orderedAscending
    }
    if b.statp.st_atim.tv_nsec < a.statp.st_atim.tv_nsec {
      return .orderedDescending
    }
    if of_samesort {
      return ComparisonResult(rawValue: strcoll(b.name, a.name))!
    }
    else {
      return ComparisonResult(rawValue: strcoll(a.name, b.name))!
    }
  }

  func revacccmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return (acccmp(b, a));
  }

  func birthcmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    if b.statp.st_birthtim.tv_sec > a.statp.st_birthtim.tv_sec {
      return .orderedAscending
    }
    if b.statp.st_birthtim.tv_sec < a.statp.st_birthtim.tv_sec {
      return .orderedDescending
    }
    if b.statp.st_birthtim.tv_nsec > a.statp.st_birthtim.tv_nsec {
      return .orderedAscending
    }
    if b.statp.st_birthtim.tv_nsec < a.statp.st_birthtim.tv_nsec {
      return .orderedAscending
    }
    if of_samesort {
      return ComparisonResult(rawValue: strcoll(b.name, a.name))!
    }
    else {
      return ComparisonResult(rawValue: strcoll(a.name, b.name))!
    }
  }

  func revbirthcmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return (birthcmp(b, a));
  }

  func statcmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    if b.statp.st_ctim.tv_sec > a.statp.st_ctim.tv_sec {
      return .orderedAscending
    }
    if b.statp.st_ctim.tv_sec < a.statp.st_ctim.tv_sec {
      return .orderedDescending
    }
    if b.statp.st_ctim.tv_nsec > a.statp.st_ctim.tv_nsec {
      return .orderedAscending
    }
    if b.statp.st_ctim.tv_nsec < a.statp.st_ctim.tv_nsec {
      return .orderedDescending
    }
    if of_samesort {
      return ComparisonResult(rawValue: strcoll(b.name, a.name))!
    }
    else {
      return ComparisonResult(rawValue: strcoll(a.name, b.name))!
    }
  }

  func revstatcmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return (statcmp(b, a));
  }

  func sizecmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    if b.statp.size > a.statp.size {
      return .orderedAscending
    }
    if b.statp.size < a.statp.size {
      return .orderedDescending
    }
    return ComparisonResult(rawValue: strcoll(a.name, b.name))!
  }

  func revsizecmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    return (sizecmp(b, a))
  }

  /*
   * Ordering for mastercmp:
   * If ordering the argv (fts_level = FTS_ROOTLEVEL) return non-directories
   * as larger than directories.  Within either group, use the sort function.
   * All other levels use the sort function.  Error entries remain unsorted.
   */
  @Sendable func mastercmp(_ a : FTSEntry, _ b : FTSEntry) -> ComparisonResult {
    if a.info == .ERR { return .orderedSame }
    if b.info == .ERR { return .orderedSame }
    if a.info == .NS || b.info == .NS { return namecmp(a, b) }

    if a.info != b.info && a.level == CMigration.FTS_ROOTLEVEL && !of_listdir {
      if a.info == .D { return .orderedDescending }
      if b.info == .D { return .orderedAscending }
    }
    return sortfcn(a, b)
  }
}
